// GAP-8: a hand-edited generated file no longer goes quiet. Every generated view (views.mjs writeViews / writeGuarded, cv.mjs) refuses
// to overwrite a file whose bytes differ from the hash Norn last wrote - and said so only on a CLI's stderr, so the file silently froze.
// handEdits lists those files from the hash files themselves (level-triggered: a file leaves the list once it matches its hash again,
// or once the owner chose). Two choices, both from the dashboard Inbox:
//   take it back - the hand version is kept as <file>.bak, its sha becomes the file's hash (the guard then lets the next write through)
//                  and the caller regenerates (the dashboard rewrites the records views at once; the others on their next write);
//   keep mine    - views/kept.json records the file + the sha of the kept text: the notice leaves, Norn still never overwrites it, and a
//                  NEW hand edit (another sha) brings the notice back.
// RM-35: each row also says what changed and who probably did it - from the write record views.mjs keeps per file (views/last/: the
// last text Norn wrote + its last writes, each with pid / role / run / engine / branch): Norn's last write, the file's mtime, whether the
// text is an OLDER Norn copy (a stale writer, not a person) or exactly Norn's last text (only its hash record was lost), whether the
// GENERATED header is still there, and a lane worktree's engine among the writers. handEditDiff serves last-written vs now for the diff.
import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { hashKey, lastFiles } from './views.mjs';
import { hhmm } from './authguard.mjs';

// the hash files of every guarded writer (views.mjs, roadmap.mjs, cv.mjs); their keys are the absolute paths Norn wrote
export const HASH_FILES = ['hashes.json', 'queue-hashes.json', 'roadmap-hashes.json', 'cv-hashes.json'];
const sha = s => crypto.createHash('sha256').update(s).digest('hex');
const fp = fs.promises;
const readJson = async (f, d) => { try { return JSON.parse(await fp.readFile(f, 'utf8')); } catch { return d; } };
const readOr = async f => { try { return await fp.readFile(f, 'utf8'); } catch { return null; } };
const keptFile = stateDir => path.join(stateDir, 'views', 'kept.json');
async function writeJson(f, v) { await fp.mkdir(path.dirname(f), { recursive: true }); const tmp = `${f}.${process.pid}.tmp`; await fp.writeFile(tmp, JSON.stringify(v, null, 1) + '\n'); await fp.rename(tmp, f); }

/** every generated file whose text is not the last text Norn wrote -> [{ file, key (both its hashKey), hashFile, sha, kept,
 * edited (mtime ISO), generated (it still carries Norn's GENERATED header: Norn's own text from another writer, not a person's edit) }];
 * kept = the owner chose to keep THIS text. Keys are hashKey()s, so kept.json and the hash files agree on one key per file. */
export async function handEdits(stateDir) {
  const vdir = path.join(stateDir, 'views'), kept = await readJson(keptFile(stateDir), {}), out = [];
  for (const h of HASH_FILES) {
    const hashFile = path.join(vdir, h), hashes = await readJson(hashFile, {});
    for (const [file, want] of Object.entries(hashes)) {
      const cur = await readOr(file);
      if (cur === null || sha(cur) === want) continue;
      let edited = null; try { edited = (await fp.stat(file)).mtime.toISOString(); } catch { /* gone meanwhile */ }
      const e = { file: hashKey(file), key: hashKey(file), hashFile, sha: sha(cur), kept: kept[hashKey(file)] === sha(cur), edited, generated: /GENERATED by norn/.test(cur.slice(0, 400)) };
      const lf = lastFiles(hashFile, file), writes = (await readJson(lf.log, null))?.writes ?? [];
      out.push({ ...e, writes: writes.slice(-5), diff: (await readOr(lf.text)) !== null, ...explain(e, writes) });
    }
  }
  return out;
}
const wtOf = w => /[\\/]wt[\\/]/.test(w.engine || '');   // an engine run from a lane worktree (state/<project>/wt/<lane>)
const byWhom = w => `${w.role || 'norn'}${w.run ? ' ' + w.run : ''}, pid ${w.pid}${w.branch ? `, engine on ${w.branch}` : ''}${wtOf(w) ? ` in ${w.engine}` : ''}`;
/** what Norn knows about one changed file, in plain words: { verdict, recommend ('takeback' | null), why (the recommendation's reason),
 * lines } - verdict: stale (an older Norn copy), lost-hash (Norn's last text, its hash record missed it), header (Norn's header, a text
 * Norn has no record of), person (the header is gone). No guess beyond the record. */
export function explain(e, writes = []) {
  const last = writes.at(-1), lines = [];
  lines.push(last ? `Norn last wrote it at ${hhmm(last.at)} (${byWhom(last)}).` : 'Norn has no record of its last write here (written before Norn kept one).');
  if (e.edited) lines.push(`The file on disk changed at ${hhmm(e.edited)}.`);
  const same = [...writes].reverse().find(w => w.sha === e.sha);
  if (same && same !== last) {
    lines.push(`Its text is an older Norn copy: Norn wrote exactly this at ${hhmm(same.at)} (${byWhom(same)}). An older Norn copy wrote this (stale), not a person.`);
    return { verdict: 'stale', recommend: 'takeback', why: "it is an older copy of Norn's own text", lines };
  }
  if (same) {
    lines.push("Its text is exactly what Norn last wrote; only Norn's hash record missed that write. Not a person.");
    return { verdict: 'lost-hash', recommend: 'takeback', why: "it is Norn's own last text", lines };
  }
  const wt = writes.filter(wtOf);
  if (wt.length) lines.push(`A Norn engine from a lane worktree also writes this file (${byWhom(wt.at(-1))}, last at ${hhmm(wt.at(-1).at)}).`);
  if (e.generated) { lines.push("It still carries Norn's GENERATED header, but Norn has no record of writing this text: most likely not edited by a person (a Norn copy that keeps no write record, or a tool that copied Norn's text). The diff shows what differs."); return { verdict: 'header', recommend: null, why: null, lines }; }
  lines.push("Norn's GENERATED header is gone, so a person or another tool edited it. The diff shows what they changed.");
  return { verdict: 'person', recommend: null, why: null, lines };
}

/** last-written (by Norn) vs now of one listed file -> { file, before (null: no text kept), after, title, sub } */
export async function handEditDiff(stateDir, file) {
  const x = await find(stateDir, file), lf = lastFiles(x.hashFile, x.file), last = x.writes.at(-1);
  return { file: x.file, before: await readOr(lf.text), after: await readOr(x.file), title: path.basename(x.file),
    sub: `last written by Norn${last ? ' ' + hhmm(last.at) : ''} vs now${x.edited ? ' (changed ' + hhmm(x.edited) + ')' : ''}` };
}

const find = async (stateDir, file) => {
  const x = (await handEdits(stateDir)).find(e => e.key === hashKey(String(file)));
  if (!x) throw Object.assign(new Error(`${file} is not a hand-edited generated file (any more): reload`), { code: 409 });
  return x;
};

/** "Let Norn take it back": the hand text to <file>.bak (or <file>.<stamp>.bak when a .bak exists), its sha recorded as the hash -> { file, bak } */
export async function takeBack(stateDir, file, { now = new Date() } = {}) {
  const x = await find(stateDir, file), cur = await fp.readFile(x.file, 'utf8');
  let bak = `${x.file}.bak`;
  if ((await readOr(bak)) !== null) bak = `${x.file}.${now.toISOString().replace(/[:.]/g, '-')}.bak`;
  await fp.writeFile(bak, cur);
  if (sha(await fp.readFile(x.file, 'utf8')) !== x.sha) throw Object.assign(new Error(`${x.file} changed while it was saved: try again`), { code: 409 });
  const hashes = await readJson(x.hashFile, {});
  hashes[x.key] = x.sha;   // the guard now takes the hand text for Norn's own: the next write replaces it
  await writeJson(x.hashFile, hashes);
  const kept = await readJson(keptFile(stateDir), {});
  if (kept[x.key] !== undefined) { delete kept[x.key]; await writeJson(keptFile(stateDir), kept); }
  return { file: x.file, bak };
}

/** "Keep my version": recorded per file + sha (views/kept.json) -> { file, sha } */
export async function keepEdit(stateDir, file) {
  const x = await find(stateDir, file), kept = await readJson(keptFile(stateDir), {});
  kept[x.key] = x.sha;
  await writeJson(keptFile(stateDir), kept);
  return { file: x.file, sha: x.sha };
}
